// UpsertConfiguredConnection updates one or more existing entries in configuredConnection collection
//
// This function is auto-generated
func (s *Store) UpsertConfiguredConnection(ctx context.Context, rr ...*systemType.ConfiguredConnection) (err error) {
	for i := range rr {
		if err = s.checkConfiguredConnectionConstraints(ctx, rr[i]); err != nil {
			return
		}

		// @todo this solution is ok for now but could be problematic when we start
		// batching together DB operations.
		if s.Dialect.Nuances().TwoStepUpsert {
			var rsp sql.Result
			rsp, err = s.ExecR(ctx, configuredConnectionUpdateQuery(s.Dialect.GOQU(), rr[i]))
			if err != nil {
				return
			}
			if c, err := rsp.RowsAffected(); err != nil {
				return err
			} else if c > 0 {
				continue
			}

			err = s.Exec(ctx, configuredConnectionInsertQuery(s.Dialect.GOQU(), rr[i]))
			if err != nil {
				return
			}
		} else {
			err = s.Exec(ctx, configuredConnectionUpsertQuery(s.Dialect.GOQU(), rr[i]))
			if err != nil {
				return
			}
		}
	}

	return
}

