// CreateConnection creates one or more rows in connection collection
//
// This function is auto-generated
func (s *Store) CreateConnection(ctx context.Context, rr ...*systemType.Connection) (err error) {
	for i := range rr {

		if err = s.checkConnectionConstraints(ctx, rr[i]); err != nil {
			return
		}

		if err = s.Exec(ctx, connectionInsertQuery(s.Dialect.GOQU(), rr[i])); err != nil {
			return
		}
	}

	return
}

// UpdateConnection updates one or more existing entries in connection collection
//
// This function is auto-generated
func (s *Store) UpdateConnection(ctx context.Context, rr ...*systemType.Connection) (err error) {
	for i := range rr {
		if err = s.checkConnectionConstraints(ctx, rr[i]); err != nil {
			return
		}
		if err = s.Exec(ctx, connectionUpdateQuery(s.Dialect.GOQU(), rr[i])); err != nil {
			return
		}
	}

	return
}

// UpsertConnection updates one or more existing entries in connection collection
//
// This function is auto-generated
func (s *Store) UpsertConnection(ctx context.Context, rr ...*systemType.Connection) (err error) {
	for i := range rr {
		if err = s.checkConnectionConstraints(ctx, rr[i]); err != nil {
			return
		}

		// @todo this solution is ok for now but could be problematic when we start
		// batching together DB operations.
		if s.Dialect.Nuances().TwoStepUpsert {
			var rsp sql.Result
			rsp, err = s.ExecR(ctx, connectionUpdateQuery(s.Dialect.GOQU(), rr[i]))
			if err != nil {
				return
			}
			if c, err := rsp.RowsAffected(); err != nil {
				return err
			} else if c > 0 {
				continue
			}

			err = s.Exec(ctx, connectionInsertQuery(s.Dialect.GOQU(), rr[i]))
			if err != nil {
				return
			}
		} else {
			err = s.Exec(ctx, connectionUpsertQuery(s.Dialect.GOQU(), rr[i]))
			if err != nil {
				return
			}
		}
	}

	return
}

