// collectKnowledgeBaseCursorValues collects values from the given resource that and sets them to the cursor
// to be used for pagination
//
// Values that are collected must come from sortable, unique or primary columns/fields
// At least one of the collected columns must be flagged as unique, otherwise fn appends primary keys at the end
//
// # Known issues:
//
// When collecting cursor values for query that sorts by unique column with partial index (ie: unique handle on
// undeleted items)
//
// This function is auto-generated
func (s *Store) collectKnowledgeBaseCursorValues(res *systemType.KnowledgeBase, cc ...*filter.SortExpr) *filter.PagingCursor {
	var (
		cur = &filter.PagingCursor{LThen: filter.SortExprSet(cc).Reversed()}

		hasUnique bool

		pkID bool

		collect = func(cc ...*filter.SortExpr) {
			getVal := func(col string) interface{} {
				switch col {
				case "id":
					pkID = true
					return res.ID
				case "handle":
					hasUnique = true
					return res.Handle
				case "createdAt":
					return res.CreatedAt
				case "updatedAt":
					return res.UpdatedAt
				case "deletedAt":
					return res.DeletedAt
				}
				return nil
			}

			for _, c := range cc {
				switch c.Modifier() {
				case filter.COALESCE:
					var val interface{}
					for _, col := range c.Columns() {
						if reflect2.IsNil(val) {
							val = getVal(col)
						}
					}
					cur.SetModifier(c.Column, val, c.Descending, c.Modifier(), c.Columns()...)
				default:
					cur.Set(c.Column, getVal(c.Column), c.Descending)
				}
			}
		}
	)

	_ = hasUnique

	collect(cc...)
	if !hasUnique || !pkID {
		collect(&filter.SortExpr{Column: "id", Descending: false})
	}

	return cur

}

// checkKnowledgeBaseConstraints performs lookups (on valid) resource to check if any of the values on unique fields
// already exists in the store
//
// Using built-in constraint checking would be more performant, but unfortunately we cannot rely
// on the full support (MySQL does not support conditional indexes)
//
// This function is auto-generated
func (s *Store) checkKnowledgeBaseConstraints(ctx context.Context, res *systemType.KnowledgeBase) (err error) {
	err = func() (err error) {

		// handling string type as default
		if len(res.Handle) == 0 {
			// skip check on empty values
			return nil
		}

		if res.DeletedAt != nil {
			// skip check if value is not nil
			return nil
		}

		ex, err := s.LookupKnowledgeBaseByHandle(ctx, res.Handle)
		if err == nil && ex != nil && ex.ID != res.ID {
			// Named, not a bare "not unique": a resource can have several
			// unique constraints and the database raises its own violations
			// too, so the message has to say which one this is.
			return store.ErrNotUniqueOn("systemType.KnowledgeBase", "Handle")
		} else if !errors.IsNotFound(err) {
			return err
		}

		return nil
	}()

	if err != nil {
		return
	}

	return nil
}

