// collectProjectPrivacyCursorValues collects values from the given resource that and sets them to the cursor
// to be used for pagination
//
// Values that are collected must come from sortable, unique or primary columns/fields
// At least one of the collected columns must be flagged as unique, otherwise fn appends primary keys at the end
//
// # Known issues:
//
// When collecting cursor values for query that sorts by unique column with partial index (ie: unique handle on
// undeleted items)
//
// This function is auto-generated
func (s *Store) collectProjectPrivacyCursorValues(res *systemType.ProjectPrivacy, cc ...*filter.SortExpr) *filter.PagingCursor {
	var (
		cur = &filter.PagingCursor{LThen: filter.SortExprSet(cc).Reversed()}

		hasUnique bool

		pkID bool

		collect = func(cc ...*filter.SortExpr) {
			getVal := func(col string) interface{} {
				switch col {
				case "id":
					pkID = true
					return res.ID
				case "revisionID":
					return res.RevisionID
				case "title":
					return res.Title
				case "requestType":
					return res.RequestType
				case "status":
					return res.Status
				case "severity":
					return res.Severity
				case "risk":
					return res.Risk
				case "requestOwner":
					return res.RequestOwner
				case "changeOwner":
					return res.ChangeOwner
				case "changeApprovedBy":
					return res.ChangeApprovedBy
				case "dateDue":
					return res.DateDue
				case "createdAt":
					return res.CreatedAt
				case "updatedAt":
					return res.UpdatedAt
				case "deletedAt":
					return res.DeletedAt
				}
				return nil
			}

			for _, c := range cc {
				switch c.Modifier() {
				case filter.COALESCE:
					var val interface{}
					for _, col := range c.Columns() {
						if reflect2.IsNil(val) {
							val = getVal(col)
						}
					}
					cur.SetModifier(c.Column, val, c.Descending, c.Modifier(), c.Columns()...)
				default:
					cur.Set(c.Column, getVal(c.Column), c.Descending)
				}
			}
		}
	)

	_ = hasUnique

	collect(cc...)
	if !hasUnique || !pkID {
		collect(&filter.SortExpr{Column: "id", Descending: false})
	}

	return cur

}

